def max_overlap_point(intervals: list[tuple[int, int]]) -> int:
    if not intervals:
        raise ValueError("intervals must not be empty")
    changes: dict[int, int] = {}
    for start, end in intervals:
        changes[start] = changes.get(start, 0) + 1
        changes[end] = changes.get(end, 0) - 1
    points = sorted(changes)
    best_point = points[0]
    best_count = 0
    coverage = 0
    for point in points:
        coverage += changes[point]
        if coverage > best_count:
            best_count = coverage
            best_point = point
    return best_point
```

